{
  "question_num": 2,
  "total_marks": 8,
  "title": "Upthrust and Floating",
  "main_stem": "A sphere floats in equilibrium on the surface of sea water of density $1050\\,\\mathrm{kg\\,m^{-3}}$, as shown in Fig. 2.1.",
  "parts": [
    {
      "label": "(a)",
      "part_stem": null,
      "text": "$21\\%$ of the volume of the sphere is below the surface of the water. Calculate the density of the sphere.",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(i)",
      "part_stem": "The sphere is now held so that its entire volume is below the surface of the water. The sphere is then released.",
      "text": "Calculate the initial acceleration of the sphere.",
      "marks": 3,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(ii)",
      "part_stem": null,
      "text": "The sphere accelerates upwards but remains entirely below the surface of the water. State and explain what happens to the acceleration of the sphere as its velocity begins to increase.",
      "marks": 3,
      "answer_prompt": null,
      "unit": null
    }
  ],
  "markscheme": [
    {
      "label": "(a)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "C1",
          "text": "upthrust = weight of displaced water or $W = \\rho \\times 9.81 \\times V$"
        },
        {
          "tag": "A1",
          "text": "$0.21 \\times 1050 \\times V(\\times 9.81) = \\rho \\times V(\\times 9.81)$; $\\rho = 220\\,\\mathrm{kg\\,m^{-3}}$"
        }
      ]
    },
    {
      "label": "(b)(i)",
      "marks": 3,
      "marking_points": [
        {
          "tag": "C1",
          "text": "upthrust $W = 1050 \\times 9.81 \\times V$"
        },
        {
          "tag": "C1",
          "text": "weight $W = 220 \\times 9.81 \\times V$"
        },
        {
          "tag": "A1",
          "text": "$(1050 - 220) \\times 9.81 \\times V = (V \\times 220) \\times a$; $a = 37\\,\\mathrm{m\\,s^{-2}}$ upwards"
        }
      ]
    },
    {
      "label": "(b)(ii)",
      "marks": 3,
      "marking_points": [
        {
          "tag": "M1",
          "text": "viscous force increases (with speed)"
        },
        {
          "tag": "M1",
          "text": "resultant force decreases (as upthrust and weight remain the same)"
        },
        {
          "tag": "A1",
          "text": "acceleration decreases (as its velocity increases)"
        }
      ]
    }
  ]
}
